    console.log('   Shi L'+R.shi+' '+R.shiB+' ['+R.shiStato+']   Ying L'+R.ying+' '+R.yingB+' ['+R.yingStato+']');
    console.log('   mobile L'+R.mutante.pos+': '+R.mutante.ramoDep+' → '+R.mutante.ramoArr+
      ' ('+R.mutante.arrElIt+')  agente '+R.mutante.effEl+'  genera: '+c.gen);
