      const ctx={oraBranch:r.oraBranch,emaDir:r.emaDir,date:r.date}; const t=LYM.termometro(R,ctx,{},{});
      if (!t.dir) add('QIFIX · LY tace', d, r); else add('QIFIX · LY parla', d, r);
