    if(cD||cM) add('§50i · mobile clashata g/m', d, r); else add('§50i · mobile libera', d, r);
    // 回頭生 alla mobile?
    if (GEN[WX[R.mutante.ramoArr]]===WX[mob.ramo]) add('§50i · con 回頭生', d, r);
    // EMA
    add('§50i · EMA '+(r.emaDir==='up'?'up':'down'), d, r);
